const ONES: [&str; 20] = [
    "zero", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine",
    "ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen",
    "seventeen", "eighteen", "nineteen",
];

const TENS: [&str; 10] = [
    "", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety",
];

const SCALES: [&str; 7] = [
    "", "thousand", "million", "billion", "trillion", "quadrillion", "quintillion",
];

fn under_hundred(n: u64) -> String {
    if n < 20 {
        ONES[n as usize].to_string()
    } else {
        let tens = n / 10;
        let ones = n % 10;
        if ones == 0 {
            TENS[tens as usize].to_string()
        } else {
            format!("{}-{}", TENS[tens as usize], ONES[ones as usize])
        }
    }
}

fn under_thousand(n: u64) -> String {
    if n < 100 {
        under_hundred(n)
    } else {
        let hundreds = n / 100;
        let rest = n % 100;
        if rest == 0 {
            format!("{} hundred", ONES[hundreds as usize])
        } else {
            format!("{} hundred {}", ONES[hundreds as usize], under_hundred(rest))
        }
    }
}

pub fn encode(n: u64) -> String {
    if n == 0 {
        return "zero".to_string();
    }
    let mut parts: Vec<String> = Vec::new();
    let mut scale = 0;
    let mut m = n;
    while m > 0 {
        let chunk = m % 1000;
        if chunk != 0 {
            let scale_word = SCALES[scale];
            if scale_word.is_empty() {
                parts.push(under_thousand(chunk));
            } else {
                parts.push(format!("{} {}", under_thousand(chunk), scale_word));
            }
        }
        m /= 1000;
        scale += 1;
    }
    parts.reverse();
    parts.join(" ")
}
```

